# Define a dictionary to hold specific values for f(r) in F_2
# This allows us to test consistency against the constraints.
# We test basic relationships like f(r) + f(-r) = 1, f(r) + f(1-r) = 1, f(r) + f(1/r) = 1.

def test_constraints(f_values):
    # Helper to safely check values
    def get_f(r):
        # Ensure r is stored as a hashable type (Fraction or float if simple)
        if isinstance(r, float) and r.is_integer():
             r = int(r)
        return f_values.get(r)

    print("--- Testing Sum=0 Constraint (r' = -r) ---")
    for r in f_values:
        r_neg = -r
        if r_neg in f_values:
            sum_val = f_values[r] + f_values[r_neg]
            if sum_val != 1:
                print(f"Error: f({r}) + f({r_neg}) = {sum_val}. Should be 1.")

    print("\n--- Testing Sum=1 Constraint (r' = 1-r) ---")
    for r in f_values:
        r_comp = 1 - r
        if r_comp in f_values:
            sum_val = f_values[r] + f_values[r_comp]
            if sum_val != 1:
                print(f"Error: f({r}) + f({r_comp}) = {sum_val}. Should be 1.")

    print("\n--- Testing Product=1 Constraint (r' = 1/r) ---")
    for r in f_values:
        # We handle r=0 separately since 1/0 is undefined
        if r == 0: continue
        r_inv = 1/r
        if r_inv in f_values:
            sum_val = f_values[r] + f_values[r_inv]
            if sum_val != 1:
                print(f"Error: f({r}) + f({r_inv}) = {sum_val}. Should be 1.")

    print("\nAll constraints satisfied for the tested values.")
    return True

